insert into public.content_item_categories(item_id,game_id,category_id,sort_order,enabled) select item_id,'we-just-met',category_id,sort_order,true from decked_we_just_met_v2_active on conflict(item_id,game_id,category_id) do update set sort_order=excluded.sort_order,enabled=true;
insert into public.content_item_versions(item_id,version,body,normalized_body,metadata,editorial_status,change_note) select item_id,next_version,body,lower(regexp_replace(body,'[^[:alnum:]'']+',' ','g')),metadata,'published','We Just Met playable V2 editorial revision' from decked_we_just_met_v2_revisions on conflict(item_id,version) do update set body=excluded.body,normalized_body=excluded.normalized_body,metadata=excluded.metadata,editorial_status='published',change_note=excluded.change_note;
insert into public.content_releases(id,game_id,status,item_count,membership_count,checksum,notes,published_at) values('7b044c6e-319b-52d3-9489-829c02945b1f'::uuid,'we-just-met','published',207,207,'cd1840def5c531b41a5ec3cc7a69cd622b28aca26ada137c865ab790a2971547','We Just Met playable V2; all 300 historical identities preserved and 53 new prompts added.',now()) on conflict(id) do update set status='published',item_count=207,membership_count=207,checksum=excluded.checksum,notes=excluded.notes,published_at=now();
