-- Recovered from the linked project's Supabase migration history.

-- We Just Met playable V2: 207 active prompts (53 new), 146 preserved archived prompts.
begin;

on conflict(id) do nothing;

on conflict(item_id,version) do nothing;

create temporary table decked_we_just_met_v2_active(item_id uuid primary key,category_id text not null,sort_order integer not null,body text not null,metadata jsonb not null,revised boolean not null) on commit drop;


do $$ declare matched integer; begin select count(*) into matched from public.content_items item join decked_we_just_met_v2_active selected on selected.item_id=item.id where item.game_id='we-just-met'; if matched<>207 then raise exception 'We Just Met V2 inventory mismatch: expected 207 IDs, found %',matched; end if; end $$;

update public.content_items set lifecycle_status='archived',updated_at=now() where game_id='we-just-met';

update public.content_items item set lifecycle_status='active',updated_at=now() from decked_we_just_met_v2_active selected where item.id=selected.item_id and item.game_id='we-just-met';

update public.content_item_categories set enabled=false where game_id='we-just-met';


create temporary table decked_we_just_met_v2_revisions on commit drop as select selected.*,item.current_version+1 next_version from decked_we_just_met_v2_active selected join public.content_items item on item.id=selected.item_id where selected.revised;

update public.content_item_versions version set editorial_status='superseded' from decked_we_just_met_v2_revisions revised where version.item_id=revised.item_id and version.version=(select published_version from public.content_items where id=revised.item_id);


update public.content_items item set current_version=revised.next_version,published_version=revised.next_version,updated_at=now() from decked_we_just_met_v2_revisions revised where item.id=revised.item_id;

update public.content_item_versions version set metadata=coalesce(version.metadata,'{}'::jsonb)||selected.metadata from decked_we_just_met_v2_active selected join public.content_items item on item.id=selected.item_id where not selected.revised and version.item_id=item.id and version.version=item.published_version;

update public.content_releases set status='superseded' where game_id='we-just-met' and status='published';


delete from public.content_release_items where release_id='7b044c6e-319b-52d3-9489-829c02945b1f'::uuid;


commit;
